<script setup lang="ts">
/**
 * A string drawn as a scannable QR Code symbol (`design/components/qr-code.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/qr-code.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onMounted, watch } from 'vue'

import { QR_QUIET_ZONE, devWarning, qrPath, qrSymbol } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/qr-code.module.css'

export type QRCodeSize = NonNullable<QRCodeProps['size']>

export type QRCodeErrorCorrection = NonNullable<QRCodeProps['errorCorrection']>

export interface QRCodeProps {
  /**
   * Damage tolerance: `L` 7%, `M` 15%, `Q` 25%, `H` 30%. More correction means a denser symbol,
   * the worse trade on a screen: displays do not get scuffed, and dense symbols scan worse at
   * arm's length. `M` is the screen default.
   */
  errorCorrection?: 'L' | 'M' | 'Q' | 'H'
  /**
   * The accessible name: what the symbol is *for* ("Authenticator setup code"), never its
   * contents. Required, because the symbol is noise to a reader who cannot scan it.
   */
  label: string
  size?: 'sm' | 'md' | 'lg'
  /**
   * The content, encoded as UTF-8; always controlled, as the symbol is a pure function of it.
   */
  value: string
}

defineOptions({ name: 'QRCode', inheritAttrs: false })

const props = withDefaults(defineProps<QRCodeProps>(), { errorCorrection: 'M', size: 'md' })
const symbol = computed(() => qrSymbol(props.value, props.errorCorrection))
const extent = computed(() => (symbol.value === null ? 0 : symbol.value.size + QR_QUIET_ZONE * 2))
const ink = computed(() => (symbol.value === null ? '' : qrPath(symbol.value, QR_QUIET_ZONE)))
const effect1 = () => {
  devWarning(
    symbol.value === null,
    `QRCode: \`value\` (${props.value.length} characters) does not fit a QR symbol at correction level ${props.errorCorrection}. Nothing was rendered.`,
  )
}
onMounted(effect1)
watch(() => [symbol.value, props.errorCorrection], effect1, { flush: 'post' })
const effect2 = () => {
  devWarning(props.value === '', 'QRCode: `value` is empty. Nothing was rendered.')
}
onMounted(effect2)
watch(() => props.value, effect2, { flush: 'post' })
</script>

<template>
  <svg
    v-if="symbol !== null && value !== ''"
    :class="styles.symbol"
    :viewBox="`0 0 ${extent} ${extent}`"
    role="img"
    :aria-label="label"
    shape-rendering="crispEdges"
    :data-size="size"
    data-mode="light"
    data-member="qr-code"
  >
    <!-- paper -->
    <rect :class="styles.paper" :width="extent" :height="extent" />
    <!-- ink -->
    <path :class="styles.ink" :d="ink" />
  </svg>
</template>
